<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Plus, Search, Pencil, Eye, ImagePlus, Layers3 } from '@lucide/vue'
import { api, list, money } from '../api'
import type { Category, Dish } from '../types'
import AppModal from '../components/AppModal.vue'
import DishArt from '../components/DishArt.vue'
const categories = ref<Category[]>([]), dishes = ref<Dish[]>([]), query = ref(''), category = ref(0), error = ref(''), formError = ref(''), busy = ref(false), loading = ref(true), modal = ref<'dish'|'category'|''>(''), editId = ref<number>(), imageFile = ref<File>()
const form = reactive({name:'',category:0,description:'',price:'',portion:'1 porsiya',available:true,archived:false})
const categoryName = ref('')
const filtered = computed(() => dishes.value.filter(d => !d.archived && (!category.value || d.category === category.value) && d.name.toLocaleLowerCase().includes(query.value.toLocaleLowerCase())))
async function load() { try { [categories.value, dishes.value] = await Promise.all([list<Category>('categories/'), list<Dish>('dishes/')]) } catch(e) { error.value = (e as Error).message } finally { loading.value = false } }
onMounted(load)
function openDish(dish?: Dish) { formError.value = ''; editId.value = dish?.id; imageFile.value = undefined; Object.assign(form, dish ? {name:dish.name,category:dish.category,description:dish.description,price:dish.price,portion:dish.portion,available:dish.available,archived:dish.archived} : {name:'',category:category.value || categories.value[0]?.id || 0,description:'',price:'',portion:'1 porsiya',available:true,archived:false}); modal.value = 'dish' }
async function saveDish() { busy.value = true; formError.value = ''; try { const body = new FormData(); Object.entries(form).forEach(([k,v]) => body.append(k,String(v))); if(imageFile.value) body.append('image',imageFile.value); await api(`dishes/${editId.value ? `${editId.value}/` : ''}`,{method:editId.value ? 'PATCH' : 'POST',body}); modal.value = ''; await load() } catch(e) { formError.value = (e as Error).message } finally { busy.value = false } }
async function saveCategory() { busy.value = true; formError.value = ''; try { await api('categories/',{method:'POST',body:JSON.stringify({name:categoryName.value,position:categories.value.length})}); modal.value = ''; categoryName.value = ''; await load() } catch(e) { formError.value = (e as Error).message } finally { busy.value = false } }
function chooseFile(event: Event) { imageFile.value = (event.target as HTMLInputElement).files?.[0] }
</script>
<template><div class="page-heading"><div><span class="eyebrow">TAOMLARINGIZ KOLLEKSIYASI</span><h1>Menyu boshqaruvi<span class="heading-dot">.</span></h1><p>Kategoriyalar, taomlar va narxlar — bir joyda.</p></div><div class="heading-actions"><button class="button secondary" @click="modal='category'; formError='' "><Layers3 :size="17"/>Kategoriya</button><button class="button primary" @click="openDish()"><Plus :size="18"/>Taom qo‘shish</button></div></div><p v-if="error" class="alert error">{{ error }}</p><div class="catalog-toolbar"><div class="tabs"><button :class="{selected:category===0}" @click="category=0">Barchasi <span>{{ dishes.filter(d=>!d.archived).length }}</span></button><button v-for="c in categories" :key="c.id" :class="{selected:category===c.id}" @click="category=c.id">{{ c.name }}</button></div><div class="search-field"><Search :size="18"/><input v-model="query" placeholder="Taomni qidirish…" aria-label="Taomni qidirish"></div></div><div v-if="loading" class="empty-state">Menyu yuklanmoqda…</div><div v-else class="dish-grid"><article v-for="dish in filtered" :key="dish.id" class="dish-card"><div class="dish-image-wrap"><DishArt :name="dish.name" :category="dish.category_name" :image="dish.image"/><span class="dish-state" :class="{unavailable:!dish.available}"><i/>{{ dish.available ? 'Mavjud' : 'Tugagan' }}</span><button class="edit-dish" :aria-label="`${dish.name} tahrirlash`" @click="openDish(dish)"><Pencil :size="16"/></button></div><div class="dish-details"><span class="eyebrow">{{ dish.category_name }}</span><h3>{{ dish.name }}</h3><p>{{ dish.description || 'Tavsif kiritilmagan' }}</p><footer><strong>{{ money(dish.price) }} <small>so‘m</small></strong><span>{{ dish.portion }}</span></footer></div></article></div><div v-if="!loading && !filtered.length" class="empty-state"><Search :size="32"/><h3>Taom topilmadi</h3><p>Qidiruvni o‘zgartiring yoki yangi taom qo‘shing.</p></div><div class="inline-tip"><Eye :size="18"/><span>Faol taomlar kassir panelida va mijoz menyusida avtomatik ko‘rinadi.</span><RouterLink to="/menu" target="_blank">Menyuni ko‘rish →</RouterLink></div><AppModal :open="modal==='category'" title="Yangi kategoriya" @close="!busy && (modal='')"><form @submit.prevent="saveCategory"><label>Kategoriya nomi<input v-model="categoryName" required maxlength="100" placeholder="Masalan, Milliy taomlar"></label><p v-if="formError" class="alert error">{{ formError }}</p><button class="button primary full" :disabled="busy">{{ busy ? 'Saqlanmoqda…' : 'Kategoriyani saqlash' }}</button></form></AppModal><AppModal :open="modal==='dish'" :title="editId ? 'Taomni tahrirlash' : 'Yangi taom'" @close="!busy && (modal='')"><form @submit.prevent="saveDish"><div class="form-row"><label>Taom nomi<input v-model="form.name" required maxlength="120" placeholder="Masalan, To‘y oshi"></label><label>Kategoriya<select v-model="form.category" required><option disabled :value="0">Kategoriyani tanlang</option><option v-for="c in categories" :value="c.id" :key="c.id">{{ c.name }}</option></select></label></div><div class="form-row"><label>Narx, so‘m<input v-model="form.price" type="number" min="1" max="9999999999" step="0.01" required></label><label>Porsiya<input v-model="form.portion" required maxlength="50" placeholder="350 g"></label></div><label>Tavsif<textarea v-model="form.description" maxlength="500" rows="3" placeholder="Tarkibi va taom haqida qisqacha…"/></label><label class="upload-field"><ImagePlus :size="24"/><span>{{ imageFile?.name || 'Taom rasmini tanlang' }}<small>JPG, PNG, WebP · 5 MB gacha</small></span><input type="file" accept="image/jpeg,image/png,image/webp" @change="chooseFile"></label><label class="checkbox"><input v-model="form.available" type="checkbox">Hozir sotuvda mavjud</label><label v-if="editId" class="checkbox"><input v-model="form.archived" type="checkbox">Arxivlash (menyudan olib tashlash)</label><p v-if="formError" class="alert error" role="alert">{{ formError }}</p><button class="button primary full" :disabled="busy">{{ busy ? 'Saqlanmoqda…' : 'Saqlash' }}</button></form></AppModal></template>
